CREATE TABLE IF NOT EXISTS staff_profiles (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), staff_id TEXT NOT NULL UNIQUE, employee_id TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, photograph_path TEXT, gender TEXT, date_of_birth TEXT, phone TEXT, address TEXT, emergency_contact_json TEXT, department_id TEXT REFERENCES departments(id), role_key TEXT, employment_type TEXT, appointment_date TEXT, contract_json TEXT, qualification TEXT, institution TEXT, certificates_json TEXT, ntc_json TEXT, professional_development_json TEXT, appraisal_json TEXT, promotion_json TEXT, documents_json TEXT, confidential_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff_assignments (id TEXT PRIMARY KEY, staff_id TEXT NOT NULL REFERENCES staff_profiles(id), subject_id TEXT REFERENCES subjects(id), class_id TEXT REFERENCES classes(id), stream_id TEXT REFERENCES streams(id), department_id TEXT REFERENCES departments(id), timetable_id TEXT, academic_year_id TEXT REFERENCES academic_years(id), term_id TEXT REFERENCES terms(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff_leave (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), staff_id TEXT NOT NULL REFERENCES staff_profiles(id), leave_type TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, reason TEXT, state TEXT NOT NULL DEFAULT 'PENDING', applied_at TEXT NOT NULL, decided_at TEXT, decided_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS staff_leave_balances (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), staff_id TEXT NOT NULL REFERENCES staff_profiles(id), leave_type TEXT NOT NULL, entitled_days REAL NOT NULL, used_days REAL NOT NULL DEFAULT 0, year TEXT NOT NULL, UNIQUE(staff_id, leave_type, year));
CREATE TABLE IF NOT EXISTS staff_documents (id TEXT PRIMARY KEY, staff_id TEXT NOT NULL REFERENCES staff_profiles(id), document_type TEXT NOT NULL, storage_key TEXT NOT NULL, uploaded_by TEXT REFERENCES users(id), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_staff_profiles_school ON staff_profiles(school_id);
CREATE INDEX IF NOT EXISTS idx_staff_leave_staff_state ON staff_leave(staff_id, state);
